184	    /**
185	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
186	     * source of truth for how an email is persisted, so inputs that differ only in letter case
187	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
188	     * (create and update, mapper or hand-copied) stores the same canonical value.
189	     *
190	     * @param email the raw email, possibly {@code null}
191	     * @return the lower-cased form, or {@code null} if the input was {@code null}
192	     */
193	    public static String normalizeEmail(String email) {
194	        return email == null ? null : email.toLowerCase();
195	    }
