197	    /**
198	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
199	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
200	     */
201	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
202	        "mailinator.com",
203	        "tempmail.com",
204	        "guerrillamail.com");
205	
206	    /**
207	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
208	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
209	     * This is the single source of truth for which email domains are rejected, shared by any
210	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
211	     *
212	     * @param email the owner's email, possibly {@code null}
213	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
214	     */
215	    public static boolean isDisposableEmailDomain(String email) {
216	        if (email == null) {
217	            return false;
218	        }
219	        int at = email.lastIndexOf('@');
220	        if (at < 0) {
221	            return false;
222	        }
223	        String domain = email.substring(at + 1).toLowerCase();
224	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
225	    }
