227	    /**
228	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
229	     * truth for how a telephone is compared and persisted, so inputs that differ only in
230	     * formatting (spaces, dashes, brackets) are treated as the same number.
231	     *
232	     * <p>The rules are:
233	     * <ul>
234	     *   <li>spaces, dashes and brackets are stripped;</li>
235	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
236	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
237	     *       is dropped from the national digits;</li>
238	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
239	     *   <li>for a recognized country code the national number (the digits after the country
240	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
241	     *       digits and {@code '+1'} requires 10.</li>
242	     * </ul>
243	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
244	     * values are returned unchanged.
245	     *
246	     * @param telephone the raw telephone, possibly {@code null}
247	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
248	     *     valid E.164 number
249	     */
250	    public static String normalizeTelephone(String telephone) {
251	        if (telephone == null) {
252	            return null;
253	        }
254	        String trimmed = telephone.trim();
255	        boolean hasCountryCode = trimmed.startsWith("+");
256	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
257	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
258	        if (hasCountryCode) {
259	            stripped = stripped.substring(1);
260	        }
261	        if (!stripped.matches("\\d+")) {
262	            return null;
263	        }
264	        String digits;
265	        if (hasCountryCode) {
266	            digits = stripped;
267	        } else {
268	            if (stripped.startsWith("0")) {
269	                stripped = stripped.substring(1);
270	            }
271	            digits = "61" + stripped;
272	        }
273	        if (digits.length() < 8 || digits.length() > 15) {
274	            return null;
275	        }
276	        if (!hasValidNationalNumberLength(digits)) {
277	            return null;
278	        }
279	        return "+" + digits;
280	    }
