282	    /**
283	     * Format a stored E.164 telephone for human display: the country code, a space, then the
284	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
285	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
286	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
287	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
288	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
289	     * kept unchanged elsewhere.
290	     *
291	     * @param telephone the stored E.164 telephone, possibly {@code null}
292	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
293	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
294	     *     unchanged
295	     */
296	    public static String telephoneDisplay(String telephone) {
297	        if (telephone == null) {
298	            return null;
299	        }
300	        if (!telephone.matches("\\+\\d+")) {
301	            return telephone;
302	        }
303	        String digits = telephone.substring(1);
304	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
305	            if (digits.startsWith(countryCode)) {
306	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
307	            }
308	        }
309	        return "+" + groupDigits(digits);
310	    }
311	
312	    /**
313	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
314	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
315	     * {@code "412345678"} becomes {@code "412 345 678"}).
316	     *
317	     * @param digits the national digits
318	     * @return the space-grouped digits
319	     */
320	    private static String groupDigits(String digits) {
321	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
322	        for (int i = 0; i < digits.length(); i++) {
323	            if (i > 0 && i % 3 == 0) {
324	                grouped.append(' ');
325	            }
326	            grouped.append(digits.charAt(i));
327	        }
328	        return grouped.toString();
329	    }
