331	    /**
332	     * Required national-number length (the count of digits after the country code) for each
333	     * recognized country code, longest country code first so the prefix match is unambiguous.
334	     */
335	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
336	    static {
337	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
338	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
339	    }
340	
341	    /**
342	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
343	     * length its country code requires. A country code with no registered length places no
344	     * additional constraint and is accepted.
345	     *
346	     * @param digits the E.164 digits without the leading {@code '+'}
347	     * @return {@code true} if the national-number length is valid for the country code
348	     */
349	    private static boolean hasValidNationalNumberLength(String digits) {
350	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
351	            String countryCode = entry.getKey();
352	            if (digits.startsWith(countryCode)) {
353	                return digits.length() - countryCode.length() == entry.getValue();
354	            }
355	        }
356	        return true;
357	    }
