359	    /**
360	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
361	     * upper-cased abbreviation.
362	     */
363	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
364	        "ST", "STREET",
365	        "RD", "ROAD",
366	        "AVE", "AVENUE");
367	
368	    /**
369	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
370	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
371	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
372	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
373	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
374	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
375	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
376	     * value. The transform is idempotent: a normalized address normalizes to itself.
377	     *
378	     * @param address the raw address, possibly {@code null}
379	     * @return the normalized form, or {@code null} if the input was {@code null}
380	     */
381	    public static String normalizeAddress(String address) {
382	        if (address == null) {
383	            return null;
384	        }
385	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
386	        if (collapsed.isEmpty()) {
387	            return collapsed;
388	        }
389	        String[] tokens = collapsed.split(" ");
390	        StringBuilder normalized = new StringBuilder(collapsed.length());
391	        for (int i = 0; i < tokens.length; i++) {
392	            if (i > 0) {
393	                normalized.append(' ');
394	            }
395	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
396	        }
397	        return normalized.toString();
398	    }
