400	    /**
401	     * Normalize a household field (such as last name or address) to its canonical form for
402	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
403	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
404	     * that differ only in letter case or spacing are treated as the same value.
405	     *
406	     * @param value the raw field value, possibly {@code null}
407	     * @return the normalized form, or {@code null} if the input was {@code null}
408	     */
409	    public static String normalizeHousehold(String value) {
410	        if (value == null) {
411	            return null;
412	        }
413	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
414	    }
415	
416	    /**
417	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
418	     * last name (compared case-insensitively with collapsed whitespace, see
419	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
420	     * those two fields, so two owners who share a last name and postcode are assigned the same id
421	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
422	     * upper-cased hex characters of the SHA-256 digest of
423	     * {@code normalizedLastName + '|' + postcode}.
424	     *
425	     * @param lastName the owner's last name, possibly {@code null}
426	     * @param postcode the owner's postcode, possibly {@code null}
427	     * @return the household id, or {@code null} if either field is {@code null}
428	     */
429	    public static String householdId(String lastName, String postcode) {
430	        String normalizedLastName = normalizeHousehold(lastName);
431	        if (normalizedLastName == null || postcode == null) {
432	            return null;
433	        }
434	        String key = normalizedLastName + "|" + postcode;
435	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
436	    }
437	
438	    /**
439	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
440	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
441	     * so they all agree on algorithm and encoding.
442	     *
443	     * @param value the string to digest, never {@code null}
444	     * @return the 64-character lower-case hex digest
445	     */
446	    private static String sha256Hex(String value) {
447	        try {
448	            byte[] digest = MessageDigest.getInstance("SHA-256")
449	                .digest(value.getBytes(StandardCharsets.UTF_8));
450	            StringBuilder hex = new StringBuilder(digest.length * 2);
451	            for (byte b : digest) {
452	                hex.append(String.format("%02x", b));
453	            }
454	            return hex.toString();
455	        } catch (NoSuchAlgorithmException e) {
456	            // SHA-256 is a standard algorithm required to be present on every JVM.
457	            throw new IllegalStateException("SHA-256 not available", e);
458	        }
459	    }
