461	    /**
462	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
463	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
464	     * <ul>
465	     *   <li>{@code REGION} is the region code derived from the postcode (see
466	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
467	     *       in no known range, and</li>
468	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
469	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
470	     *       name.</li>
471	     * </ul>
472	     * The value is deterministic in the postcode, telephone and last name (e.g.
473	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
474	     *
475	     * @param postcode the owner's postcode, possibly {@code null}
476	     * @param telephone the owner's raw telephone, possibly {@code null}
477	     * @param lastName the owner's last name, possibly {@code null}
478	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
479	     */
480	    public static String customerCode(String postcode, String telephone, String lastName) {
481	        if (telephone == null || lastName == null) {
482	            return null;
483	        }
484	        String region = regionForPostcode(postcode);
485	        if (region == null) {
486	            region = "UNKNOWN";
487	        }
488	        String normalizedTelephone = normalizeTelephone(telephone);
489	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
490	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
491	    }
492	
493	    /**
494	     * Compute an owner's {@code identityKey}, the single derived value through which all
495	     * duplicate detection is now expressed. It consolidates the three formerly separate
496	     * telephone, email and household duplicate checks into one key, formatted as
497	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
498	     * <ul>
499	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
500	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
501	     *       when no email is present, and</li>
502	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
503	     * </ul>
504	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
505	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
506	     * members of the same household with different telephones have different keys.
507	     *
508	     * @param telephone the owner's raw telephone, possibly {@code null}
509	     * @param email the owner's email, possibly {@code null}
510	     * @param lastName the owner's last name, possibly {@code null}
511	     * @param postcode the owner's postcode, possibly {@code null}
512	     * @return the identity key, never {@code null}
513	     */
514	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
515	        String normalizedTelephone = normalizeTelephone(telephone);
516	        String normalizedEmail = normalizeEmail(email);
517	        String household = householdId(lastName, postcode);
518	        return (normalizedTelephone == null ? "" : normalizedTelephone)
519	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
520	            + "|" + (household == null ? "" : household);
521	    }
