523	    /**
524	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
525	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
526	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
527	     * value is deterministic in those two fields.
528	     *
529	     * @param customerCode the owner's customer code, possibly {@code null}
530	     * @param registrationDate the owner's registration date, possibly {@code null}
531	     * @return the membership number, or {@code null} if either field is {@code null}
532	     */
533	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
534	        if (customerCode == null || registrationDate == null) {
535	            return null;
536	        }
537	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
538	    }
