540	    /**
541	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
542	     * value starts at 1, gains 1 when an email is present, gains 1 when {@code namesakeCount} is 0,
543	     * and gains 1 when the owner's tenure is more than 365 days (the tenure being the number of days
544	     * from {@code registrationDate} to today). Level 4 therefore requires tenure of more than 365
545	     * days: because a newly created owner has zero tenure, a new owner never exceeds level 3. The
546	     * value is capped at 4.
547	     *
548	     * @param namesakeCount the owner's namesake count, possibly {@code null}
549	     * @param email the owner's email, possibly {@code null}
550	     * @param registrationDate the owner's registration date, possibly {@code null}
551	     * @return the membership level, an integer from 1 to 4
552	     */
553	    public static int membershipLevel(Integer namesakeCount, String email, LocalDate registrationDate) {
554	        int level = 1;
555	        if (email != null && !email.isEmpty()) {
556	            level++;
557	        }
558	        if (namesakeCount != null && namesakeCount == 0) {
559	            level++;
560	        }
561	        if (registrationDate != null
562	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
563	            level++;
564	        }
565	        return Math.min(level, 4);
566	    }
