568	    /**
569	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
570	     * for postcode validation, keyed by the exact city name.
571	     */
572	    private static final Map<String, String> CITY_REGION = Map.of(
573	        "Sydney", "NSW",
574	        "Melbourne", "VIC",
575	        "Brisbane", "QLD");
