577	    /**
578	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
579	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
580	     * Because the customer code's region is itself derived from the postcode, the locality now shares
581	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
582	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
583	     *
584	     * @param customerCode the owner's customer code, possibly {@code null}
585	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
586	     */
587	    public static String locality(String customerCode) {
588	        if (customerCode == null) {
589	            return "UNKNOWN";
590	        }
591	        int dash = customerCode.indexOf('-');
592	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
593	    }
594	
595	    /**
596	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
597	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
598	     *
599	     * @param city the owner's city, possibly {@code null}
600	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
601	     */
602	    private static String regionForCity(String city) {
603	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
604	    }
605	
606	    /**
607	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
608	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
609	     * inclusive low and high bound of the region's valid 4-digit postcodes
610	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
611	     * table (including {@code 'UNKNOWN'}) places no range constraint.
612	     */
613	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
614	        "NSW", new int[] {2000, 2099},
615	        "VIC", new int[] {3000, 3099},
616	        "QLD", new int[] {4000, 4099});
617	
618	    /**
619	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
620	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
621	     * digits, or one that falls in no known range resolves to {@code null}.
622	     *
623	     * @param postcode the owner's postcode, possibly {@code null}
624	     * @return the matching region, or {@code null} when no range contains the postcode
625	     */
626	    private static String regionForPostcode(String postcode) {
627	        if (postcode == null || !postcode.matches("\\d{4}")) {
628	            return null;
629	        }
630	        int value = Integer.parseInt(postcode);
631	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
632	            int[] range = entry.getValue();
633	            if (value >= range[0] && value <= range[1]) {
634	                return entry.getKey();
635	            }
636	        }
637	        return null;
638	    }
639	
640	    /**
641	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
642	     * {@code null} or empty postcode is always valid. When present it must be exactly four
643	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
644	     * range the value must fall within that inclusive range. A city with no known region accepts
645	     * any four-digit postcode. This is the single source of
646	     * truth for postcode validity, shared by the DTO validation and any persistence path.
647	     *
648	     * @param postcode the owner's postcode, possibly {@code null}
649	     * @param city the owner's city, possibly {@code null}
650	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
651	     */
652	    public static boolean isPostcodeValidForCity(String postcode, String city) {
653	        if (postcode == null || postcode.isEmpty()) {
654	            return true;
655	        }
656	        if (!postcode.matches("\\d{4}")) {
657	            return false;
658	        }
659	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
660	        if (range == null) {
661	            return true;
662	        }
663	        int value = Integer.parseInt(postcode);
664	        return value >= range[0] && value <= range[1];
665	    }
666	
667	    /**
668	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
669	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
670	     * value is deterministic in the customer code and is the standard Luhn check digit: each
671	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
672	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
673	     * brings the weighted sum up to the next multiple of ten.
674	     *
675	     * @param customerCode the owner's customer code, possibly {@code null}
676	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
677	     */
678	    public static Integer checkDigit(String customerCode) {
679	        if (customerCode == null) {
680	            return null;
681	        }
682	        int sum = 0;
683	        boolean dbl = true;
684	        for (int i = customerCode.length() - 1; i >= 0; i--) {
685	            char c = customerCode.charAt(i);
686	            if (c < '0' || c > '9') {
687	                continue;
688	            }
689	            int d = c - '0';
690	            if (dbl) {
691	                d *= 2;
692	                if (d > 9) {
693	                    d -= 9;
694	                }
695	            }
696	            sum += d;
697	            dbl = !dbl;
698	        }
699	        return (10 - (sum % 10)) % 10;
700	    }
701	
702	    /**
703	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
704	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
705	     * is deterministic in the email.
706	     *
707	     * @param email the owner's email, possibly {@code null}
708	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
709	     */
710	    public static String contactPreference(String email) {
711	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
712	    }
713	
714	    /**
715	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
716	     * date. The age in whole years is the number of completed years between {@code birthDate} and
717	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
718	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
719	     * two fields and is only defined when both are present.
720	     *
721	     * @param birthDate the owner's date of birth, possibly {@code null}
722	     * @param registrationDate the owner's registration date, possibly {@code null}
723	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
724	     *     is {@code null}
725	     */
726	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
727	        if (birthDate == null || registrationDate == null) {
728	            return null;
729	        }
730	        int age = Period.between(birthDate, registrationDate).getYears();
731	        if (age < 18) {
732	            return "MINOR";
733	        }
734	        if (age < 65) {
735	            return "ADULT";
736	        }
737	        return "SENIOR";
738	    }
739	
740	    protected Set<Pet> getPetsInternal() {
741	        if (this.pets == null) {
742	            this.pets = new HashSet<>();
743	        }
744	        return this.pets;
745	    }
746	
747	    protected void setPetsInternal(Set<Pet> pets) {
748	        this.pets = pets;
749	    }
750	
751	    public List<Pet> getPets() {
752	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
753	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
754	        return Collections.unmodifiableList(sortedPets);
755	    }
756	
757	    public void setPets(List<Pet> pets) {
758	        this.pets = new HashSet<>(pets);
759	    }
760	
761	    public void addPet(Pet pet) {
762	        getPetsInternal().add(pet);
763	        pet.setOwner(this);
764	    }
765	
766	    /**
767	     * Return the Pet with the given name, or null if none found for this Owner.
768	     *
769	     * @param name to test
770	     * @return true if pet name is already in use
771	     */
772	    public Pet getPet(String name) {
773	        return getPet(name, false);
774	    }
775	
776	    /**
777	     * Return the Pet with the given name, or null if none found for this Owner.
778	     *
779	     * @param name to test
780	     * @return true if pet name is already in use
781	     */
782	    public Pet getPet(String name, boolean ignoreNew) {
783	        name = name.toLowerCase();
784	        for (Pet pet : getPetsInternal()) {
785	            if (!ignoreNew || !pet.isNew()) {
786	                String compName = pet.getName();
787	                compName = compName.toLowerCase();
788	                if (compName.equals(name)) {
789	                    return pet;
790	                }
791	            }
792	        }
793	        return null;
794	    }
795	
796	    public Pet getPet(Integer petId) {
797	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
798	    }
799	
800	    @Override
801	    public String toString() {
802	        return new ToStringCreator(this)
803	
804	            .append("id", this.getId())
805	            .append("new", this.isNew())
806	            .append("lastName", this.getLastName())
807	            .append("firstName", this.getFirstName())
808	            .append("address", this.address)
809	            .append("city", this.city)
810	            .append("telephone", this.telephone)
811	            .toString();
812	    }
813	}
